// src/pages/Contact.js

import React from 'react';

const Contact = () => {
    return (
        <div className="container mx-auto my-8 p-4 main_content">
            <h1 className="text-3xl font-bold mb-4">联系方式</h1>
            <p>既然你打开了这个网站，那么大概率访问过了我的微信公众号了。</p>
            <p>其它联系方式会在后续添加。</p>
        </div>
    );
};

export default Contact;
